def methods(t):return {n.name:n for n in model(t).body if isinstance(n,ast.FunctionDef)}
def dump(n):return ast.dump(n,include_attributes=False)
om=methods(old)
changed={'__init__','_represent','_target_match_summary','_select_summary_alignment'}
