 s=p.read_text(); compile(s,str(p),'exec');t=ast.parse(s);m=methods(t)
 cfg=ast.literal_eval(next(n.value for n in t.body if isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='CONFIG' for x in n.targets)))
 init=m['__init__'];defaults={n.arg:ast.literal_eval(v) for n,v in zip(init.args.args[-len(init.args.defaults):],init.args.defaults)}
 assert all(defaults[k]==v for k,v in cfg.items())
 for name in om:
  if name not in changed:assert dump(m[name])==dump(om[name]),name
 def learned_tail(f):
  i=next(i for i,n in enumerate(f.body) if isinstance(n,ast.Assign) and any(isinstance(x,ast.Attribute) and x.attr=='embedding_layer' for x in n.targets))
  return [dump(n) for n in f.body[i:]]
 assert learned_tail(init)==learned_tail(om['__init__'])
 for n in ast.walk(t):
  if isinstance(n,(ast.Import,ast.ImportFrom)):
   names=[x.name for x in n.names] if isinstance(n,ast.Import) else [n.module]
   assert all(x.split('.')[0] in {'torch','unirank'} for x in names)
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name):assert n.func.id not in {'open','eval','exec','__import__','compile'}
 # All source differences must reduce to CONFIG and two constructor defaults.
 for n in t.body:
  if isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='CONFIG' for x in n.targets):n.value=ast.Constant(value=None)
 for arg,value in zip(init.args.args[-len(init.args.defaults):],init.args.defaults):
  if arg.arg in {'summary_rotation_group','residual_routing'}:value.value='NORMALIZED'
 normalized.append(dump(t))
 print(p.name,'syntax/config/imports/unchanged methods/learned construction PASS',hashlib.sha256(s.encode()).hexdigest())
assert len(set(normalized))==1
print('four-source parity PASS')
# Exhaustive scalar oracle of the inherited valid-rank indexing, not a tensor test.
changed_masks=0
for bits in range(1024):
 valid=[bool(bits&(1<<i)) for i in range(10)]
 positions=[i for i,v in enumerate(valid) if v];count=len(positions)
 packed=[0]*10; ranks=[];r=-1
 for i,v in enumerate(valid):
  r+=int(v);rank=max(r,0);ranks.append(rank);packed[rank]+=i*int(v)
 mapped=[packed[(ranks[i]+count//2)%max(count,1)] if valid[i] else i for i in range(10)]
 assert sorted(mapped[i] for i in positions)==positions
 assert all(mapped[i]==i for i in range(10) if not valid[i])
 assert count>1 or mapped==list(range(10))
 # Constant-within-block contractions are exactly invariant over integers.
 assert sum(mapped[i] for i in positions)==sum(positions)
 changed_masks+=int(any(mapped[i]"'!=i for i in positions))
print('"'scalar indexing oracle PASS: 1024 block masks;',changed_masks,'nonidentity masks for distinct actions; no tensor/gradient check')
PY"

